import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [pantalla, setPantalla] = useState('catalogo'); // Vistas: 'catalogo', 'formulario', 'reporte'
  const [productos, setProductos] = useState([]);

  // Registro de ventas del día actual para el reporte financiero
  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  // Captura automática de la fecha del sistema local
  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
  });

  // Estados del formulario de ingreso
  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [imagenUrl, setImagenUrl] = useState('https://images.unsplash.com/photo-1628102477218-097561f38e6f?q=80&w=300&auto=format&fit=crop');
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState(2500);
  const [stock, setStock] = useState(20);

  // Guardar ventas en el almacenamiento local del navegador para no perder el día si se refresca
  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  // Cargar inventario inicial desde Spring Boot al arrancar
  useEffect(() => {
    obtenerInventarioBackend();
  }, []);

  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) {
      console.error("Error al sincronizar con Spring Boot:", error);
    }
  };

  // Cálculo de márgenes comerciales sugeridos
  const porcentajeIVA = parseFloat(impuesto) / 100;
  const costoConIVA = precioCosto * (1 + porcentajeIVA);
  const margenSugerido = costoConIVA * 1.30;

  const formatearMoneda = (valor) => {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0
    }).format(valor);
  };

  // CONTROL DE DUPLICADOS Y REGISTRO
  const handleGuardar = async (e) => {
    e.preventDefault();

    // Validar si el producto ya existe en el catálogo actual (Ignora mayúsculas/minúsculas)
    const productoExistente = productos.find(
      (p) => p.nombre.toLowerCase().trim() === nombre.toLowerCase().trim()
    );

    let nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl,
      precioCosto: parseFloat(precioCosto),
      impuesto: parseFloat(impuesto),
      precioVenta: parseFloat(precioVenta),
      stock: parseInt(stock)
    };

    // Si ya existe, se actualiza el stock sumando el anterior y se hereda el ID de base de datos
    if (productoExistente) {
      nuevoProducto.id = productoExistente.id;
      nuevoProducto.stock = productoExistente.stock + parseInt(stock);
    }

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert(productoExistente ? "¡Producto duplicado detectado! Se ha incrementado el stock existente." : "¡Nuevo producto añadido al catálogo!");
        obtenerInventarioBackend();
        setPantalla('catalogo');
      }
    } catch (error) {
      alert("Error al intentar procesar la operación en Java.");
    }
  };

  // LOGICA DE NEGOCIO: REGISTRAR UNA VENTA EN VIVO
  const registrarVenta = (producto) => {
    if (producto.stock <= 0) {
      alert(`¡Alerta! No queda stock disponible de ${producto.nombre}.`);
      return;
    }

    // 1. Descontar del inventario local/backend inmediatamente
    const inventarioActualizado = productos.map((p) => {
      if (p.id === producto.id) {
        return { ...p, stock: p.stock - 1 };
      }
      return p;
    });
    setProductos(inventarioActualizado);

    // 2. Calcular la ganancia individual de esta venta unitaria
    const ivaIndividual = (producto.precioCosto * producto.impuesto) / 100;
    const costoRealConIva = producto.precioCosto + ivaIndividual;
    const gananciaNetaGenerada = producto.precioVenta - costoRealConIva;

    // 3. Empujar la venta al registro del reporte
    const nuevaVenta = {
      id: Date.now(),
      nombre: producto.nombre,
      precioVenta: producto.precioVenta,
      costoConIva: costoRealConIva,
      gananciaNeta: gananciaNetaGenerada,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };

    setVentasDelDia([...ventasDelDia, nuevaVenta]);
  };

  // Vaciar el registro para arrancar una nueva jornada matutina
  const limpiarCierreCaja = () => {
    if (window.confirm("¿Seguro que deseas cerrar la jornada actual? Esto limpiará el reporte de hoy.")) {
      setVentasDelDia([]);
      localStorage.removeItem('ventas_paisita');
    }
  };

  // Métricas financieras del reporte
  const ingresosTotales = ventasDelDia.reduce((sum, v) => sum + v.precioVenta, 0);
  const gananciasTotalesNetas = ventasDelDia.reduce((sum, v) => sum + v.gananciaNeta, 0);

  return (
    <div className="app-layout">

      {/* HEADER DE CONTROL TEMPORAL */}
      <header className="app-header">
        <div className="header-brand">
          <h1>El Paisita UP</h1>
          <p className="fecha-badge">📅 {fechaHoy}</p>
        </div>

        <nav className="header-nav">
          <button className={`nav-link ${pantalla === 'catalogo' ? 'active' : ''}`} onClick={() => setPantalla('catalogo')}>📦 Catálogo</button>
          <button className={`nav-link ${pantalla === 'formulario' ? 'active' : ''}`} onClick={() => setPantalla('formulario')}>➕ Ingresar Mercancía</button>
          <button className={`nav-link-alert ${pantalla === 'reporte' ? 'active' : ''}`} onClick={() => setPantalla('reporte')}>📊 Cierre de Caja ({ventasDelDia.length})</button>
        </nav>
      </header>

      <main className="app-content">

        {/* PANTALLA 1: CATÁLOGO TIPO GRILLA COMERCIAL */}
        {pantalla === 'catalogo' && (
          <div className="catalogo-view">
            <div className="seccion-titulo">
              <h2>Inventario Disponible</h2>
              <p>Monitoreo y venta directa de mercancía sin duplicados en el sistema</p>
            </div>

            {productos.length === 0 ? (
              <div className="empty-state">No hay mercancía registrada en el catálogo.</div>
            ) : (
              <div className="grid-catalogo">
                {productos.map((prod) => (
                  <div key={prod.id} className="card-producto">
                    <div className="card-image-wrapper">
                      <img src={prod.imagenUrl} alt={prod.nombre} onError={(e)=>{e.target.src="https://images.unsplash.com/photo-1546069901-ba9599a7e63c?q=80&w=300"}} />
                      <span className="categoria-tag">{prod.categoria}</span>
                    </div>
                    <div className="card-info">
                      <h3>{prod.nombre}</h3>
                      <div className="card-precios">
                        <div className="precio-item">
                          <span className="label-precio">Venta</span>
                          <span className="valor-venta">{formatearMoneda(prod.precioVenta)}</span>
                        </div>
                        <div className="precio-item text-right">
                          <span className="label-precio">Costo base</span>
                          <span className="valor-costo">{formatearMoneda(prod.precioCosto)}</span>
                        </div>
                      </div>

                      <div className="stock-status-bar">
                        <span className="stock-count">Stock: <strong>{prod.stock} uds</strong></span>
                        <div className="progreso-stock" style={{width: `${Math.min((prod.stock/50)*100, 100)}%`, backgroundColor: prod.stock < 5 ? '#E8C5C8' : '#C1D7C3'}}></div>
                      </div>

                      <button className="btn-vender-card" onClick={() => registrarVenta(prod)} disabled={prod.stock <= 0}>
                        {prod.stock <= 0 ? '🚫 Sin Existencias' : '🛒 Registrar Venta (1u)'}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* PANTALLA 2: FORMULARIO MEJORADO */}
        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            <div className="form-card">
              <h2 className="form-title">Ingreso de Lote <span>Mapeo inteligente automático si el nombre coincide</span></h2>
              <form onSubmit={handleGuardar}>
                <div className="form-group">
                  <label className="form-label">Nombre del Producto</label>
                  <input type="text" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" required />
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Categoría</label>
                    <input type="text" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Imagen (URL)</label>
                    <input type="text" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} className="form-input" />
                  </div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Precio Costo</label>
                    <input type="number" value={precioCosto} onChange={(e) => setPrecioCosto(Number(e.target.value))} className="form-input" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Impuesto</label>
                    <select value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input">
                      <option value="19">IVA 19% (General CO)</option>
                      <option value="8">INC 8% (Consumo)</option>
                      <option value="0">Exento</option>
                    </select>
                  </div>
                </div>
                <div className="suggested-box">
                  <p className="suggested-title">Margen de Rentabilidad Sugerido (30%)</p>
                  <div className="suggested-price">{formatearMoneda(margenSugerido)}</div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Precio Final Venta</label>
                    <input type="number" value={precioVenta} onChange={(e) => setPrecioVenta(Number(e.target.value))} className="form-input" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Cantidad Entrante (Stock)</label>
                    <input type="number" value={stock} onChange={(e) => setStock(Number(e.target.value))} className="form-input" required />
                  </div>
                </div>
                <button type="submit" className="btn-submit">Procesar e Inyectar al Catálogo</button>
              </form>
            </div>
          </div>
        )}

        {/* PANTALLA 3: REPORTE DE FIN DE DÍA */}
        {pantalla === 'reporte' && (
          <div className="reporte-view">
            <div className="kpi-dashboard">
              <div className="kpi-card text-pastel-pink">
                <h3>Ventas Realizadas</h3>
                <p className="kpi-valor">{ventasDelDia.length} transacciones</p>
              </div>
              <div className="kpi-card text-pastel-blue">
                <h3>Caja Bruta Recaudada</h3>
                <p className="kpi-valor">{formatearMoneda(ingresosTotales)}</p>
              </div>
              <div className="kpi-card text-pastel-green">
                <h3>Ganancia Real Recaudada</h3>
                <p className="kpi-valor">{formatearMoneda(gananciasTotalesNetas)}</p>
                <span className="kpi-subtext">Restando costos bases y cargas tributarias de IVA</span>
              </div>
            </div>

            <div className="form-card full-width-card">
              <div className="reporte-header">
                <h2>Bitácora de Auditoría Diaria</h2>
                <button className="btn-clean-caja" onClick={limpiarCierreCaja}>🔒 Hacer Cierre de Caja Diario</button>
              </div>
              {ventasDelDia.length === 0 ? (
                <p className="empty-state">No se registran operaciones en la fecha actual.</p>
              ) : (
                <table className="tabla-reporte">
                  <thead>
                    <tr>
                      <th>Hora de Ejecución</th>
                      <th>Ítem Comercial</th>
                      <th>Precio Cobrado</th>
                      <th>Costo con IVA</th>
                      <th>Ganancia Limpia</th>
                    </tr>
                  </thead>
                  <tbody>
                    {ventasDelDia.map((v) => (
                      <tr key={v.id}>
                        <td>{v.hora}</td>
                        <td className="font-medium text-[#E3CBB3]">{v.nombre}</td>
                        <td>{formatearMoneda(v.precioVenta)}</td>
                        <td>{formatearMoneda(v.costoConIva)}</td>
                        <td className="text-[#C1D7C3] font-semibold">+{formatearMoneda(v.gananciaNeta)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        )}

      </main>
    </div>
  );
}

export default App;
